package dev.instaghost.module.core

import org.junit.Assert.*
import org.junit.Test

class DescriptorPolicyTest {
    @Test fun parsesNormalAndEmptyParameterDescriptors() {
        assertEquals(listOf("int", "java.lang.String"), DescriptorPolicy.parse("pkg.Type#method#int,java.lang.String")?.parameters)
        assertEquals(emptyList<String>(), DescriptorPolicy.parse("pkg.Type#method#")?.parameters)
    }
    @Test fun supportsArrayTypes() {
        assertNotNull(DescriptorPolicy.parse("pkg.Type#method#[I,[Ljava.lang.String;"))
    }
    @Test fun rejectsMalformedDescriptors() {
        listOf("", "a#b", "#b#", "a##", "a#bad name#", "a#b#unknown type",
            "a#b#int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int", "a#b#").forEach {
            assertNull("expected rejection: $it", DescriptorPolicy.parse(it))
        }
    }
}
